import React from "react";
import { useI18next } from "gatsby-plugin-react-i18next";
import type { LanguageSelectorProps } from "../interfaces";

const LANGUAGE_LABELS: Record<string, string> = {
  en: "English",
  fr: "Français",
  es: "Español",
};

const SCROLL_POSITION_KEY = "language-switch-scroll-position";

const LanguageSelector: React.FC<LanguageSelectorProps> = ({ data }) => {
  const { languages, changeLanguage, language: currentLanguage } = useI18next();

  if (!data?.menu) {
    return null;
  }

  return (
    <div className={styles.container}>
      <ul className={styles.buttonsWrapper}>
        {languages.map((lng) => (
          <li
            key={lng}
            className={` ${styles.text} ${lng === currentLanguage ? "font-bold" : ""}`}
            onClick={(e) => {
              e.preventDefault();
              if (typeof window !== "undefined") {
                window.sessionStorage.setItem(
                  SCROLL_POSITION_KEY,
                  JSON.stringify({ x: window.scrollX, y: window.scrollY }),
                );
              }
              changeLanguage(lng);
            }}
          >
            <div className={`${styles.text} ${lng === currentLanguage ? " !text-light" : ""}`}>
              {LANGUAGE_LABELS[lng] ?? lng}
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default LanguageSelector;

const styles = {
  container: "flex flex-row justify-center self-center relative subtext_desk text-main",
  buttonsWrapper: "flex justify-evenly flex-row",
  text: "self-center cursor-pointer mx-0.5",
};
