import React from "react";
import Navigation from "../components/nav";
import { SiInstagram } from "react-icons/si";
import { SiTiktok } from "react-icons/si";
import { ImFacebook2 } from "react-icons/im";
import images from "../images";
import data from "../data/data.json";
import type { LayoutData, LayoutProps } from "../interfaces";

const userData: LayoutData = data;
const SCROLL_POSITION_KEY = "language-switch-scroll-position";

const Layout: React.FC<LayoutProps> = ({ children, data }) => {
  const currentYear = new Date().getFullYear();

  React.useEffect(() => {
    if (typeof window === "undefined") {
      return;
    }

    const savedPosition = window.sessionStorage.getItem(SCROLL_POSITION_KEY);
    if (!savedPosition) {
      return;
    }

    window.sessionStorage.removeItem(SCROLL_POSITION_KEY);

    try {
      const { x = 0, y = 0 } = JSON.parse(savedPosition) as { x?: number; y?: number };
      window.requestAnimationFrame(() => {
        window.requestAnimationFrame(() => {
          window.scrollTo(x, y);
        });
      });
    } catch {
      window.scrollTo(0, 0);
    }
  }, []);

  const footerData = {
    name: data?.companyName || data?.name || userData.companyName || userData.name,
    phone: data?.phone || userData.phone,
    address: data?.address || userData.address,
    city: data?.city || userData.city,
    province: data?.province || userData.province,
    country: data?.country || userData.country || "Canada",
    instagram: data?.instagram || userData.instagram,
    facebook: data?.facebook || userData.facebook,
    tiktok: data?.tiktok || userData.tiktok,
  };

  const addressLine = [
    footerData.address,
    footerData.city,
    footerData.province,
    footerData.country,
  ]
    .filter(Boolean)
    .join(", ");

  function formatPhoneNumber(phoneNumber: string) {
    const cleanedPhoneNumber = phoneNumber.replace(/\D+/g, "");
    if (cleanedPhoneNumber.startsWith("1")) {
      return `+1 ${cleanedPhoneNumber.slice(1, 4)} ${cleanedPhoneNumber.slice(
        4,
        7,
      )} ${cleanedPhoneNumber.slice(7, 12)}`;
    } else {
      return cleanedPhoneNumber;
    }
  }

  return (
    <>
      <div id={data?.menu?.[0]} className={styles.container}>
        <section
        className={styles.backgroundImage}
        style={{ backgroundImage: `url(${images.logo.src})` }}
      ></section>
        <header className={styles.header}>

          <Navigation />
        </header>
        <div className="relative">
          {children}</div>
      </div>

      <footer className={styles.footerContainer} id={userData.menu?.[4]}>
        <figure className={styles.footerWatermark} aria-hidden="true">
          <img
            className={styles.footerWatermarkImage}
            src={images.logo.src}
            alt={images.logo.alt}
          />
        </figure>

        <section className={styles.footerContent}>
          <div className={styles.footerTop}>
            <article className={styles.footerBlock}>
              <div className={styles.socialLinks}>
                {footerData.instagram ? (
                  <a
                    href={footerData.instagram}
                    target="_blank"
                    rel="noreferrer"
                    aria-label="Instagram"
                    className={styles.socialLink}
                  >
                    <SiInstagram aria-hidden="true" focusable="false" />
                  </a>
                ) : null}
                {footerData.facebook ? (
                  <a
                    href={footerData.facebook}
                    target="_blank"
                    rel="noreferrer"
                    aria-label="Facebook"
                    className={styles.socialLink}
                  >
                    <ImFacebook2 aria-hidden="true" focusable="false" />
                  </a>
                ) : null}
                {footerData.tiktok ? (
                  <a
                    href={footerData.tiktok}
                    target="_blank"
                    rel="noreferrer"
                    aria-label="TikTok"
                    className={styles.socialLink}
                  >
                    <SiTiktok aria-hidden="true" focusable="false" />
                  </a>
                ) : null}
              </div>
            </article>

            <div className={`${styles.footerBlock} !flex-col`}>
              {footerData.phone ? (
                <a
                  href={`tel:${footerData.phone}`}
                  className={styles.footerPhone}
                >
                  {formatPhoneNumber(footerData.phone)}
                </a>
              ) : null}
              {addressLine ? (
                <address className={styles.footerAddress}>
                  {addressLine}
                </address>
              ) : null}

            </div>
          </div>

          <div className={styles.footerBottom}>
            <span>
              &copy; {currentYear} {footerData.name}
            </span>
          </div>
        </section>
      </footer>
    </>
  );
};

export default Layout;

const styles = {
  container: "mx-auto",
  header:"items-center gap-2 px-0 py-0 shadow-lg sticky top-0 z-50 top-0",
  // leftGroup: "col-start-2 row-start-1 min-w-0 justify-self-center sm:col-start-1 sm:justify-self-auto",
  // brandLink: "block text-main h1_mobile sm:h1_desk truncate ml-2 sm:ml-0 pr-0 sm:pr-2 py-1",
  footerContainer: "relative overflow-hidden bg-secondary text-contrast",
  footerWatermark:
    "pointer-events-none absolute left-1/2 top-1/2 -z-0 flex -translate-x-1/2 -translate-y-1/2 items-center justify-center opacity-10",
  footerWatermarkImage: "h-[18rem] w-[18rem] object-contain sm:h-[24rem] sm:w-[24rem]",
  footerContent: "relative z-10 mx-auto flex w-full max-w-[1400px] flex-col gap-6 px-4 py-8 sm:px-8",
  footerTop: "grid gap-6 text-center md:grid-cols-2 md:text-center w-1/2 mx-auto",
  footerBlock: "flex items-center justify-center md:justify-start",
  socialLinks: "flex items-center gap-4",
  socialLink:
    "inline-flex h-11 w-11 items-center justify-center rounded-full border border-contrast/25 text-2xl text-contrast transition-colors duration-200 hover:border-terciary hover:text-terciary",
  footerPhone: "h3_desk text-contrast transition-colors duration-200 hover:text-terciary",
  footerAddress: "not-italic body_desk max-w-md text-contrast/85",
  footerBottom:
    "border-t border-contrast/15 pt-4 text-center subtext_desk uppercase tracking-wide text-contrast/70",
  // logoContainer: "col-start-1 row-start-1 flex justify-center items-center sm:col-start-2",
  // logo: "h-[60px]",
  backgroundImage:
    "fixed inset-0 left-0 top-1/4 bg-no-repeat bg-cover bg-center before:content-[''] before:absolute before:inset-0 before:bg-white/80 w-1/4 h-1/2 opacity-20",
};
