import React, { useState } from "react";
import { useLocation } from "@reach/router";
import { FiMenu, FiX } from "react-icons/fi";
import { useTranslation } from "gatsby-plugin-react-i18next";
import menuData from "../data/data.json";
import data from "../data/data.json";
import LanguageSelector from "./languageSelector";
import images from "../images";
import { LayoutData } from "../interfaces";


const userData: LayoutData = data;

function normalizePathname(pathname: string): string {
  const withoutLocalePrefix = pathname.replace(/^\/(en|fr|es)(?=\/|$)/, "");
  const normalizedPath = withoutLocalePrefix || "/";

  if (normalizedPath !== "/" && normalizedPath.endsWith("/")) {
    return normalizedPath.slice(0, -1);
  }

  return normalizedPath;
}

function getSubmenuTranslationKey(item: string): string {
  if (item === "cruises") {
    return "home.Cruises";
  }

  return `home.${item}`;
}

export default function Navigation() {
  const { t } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  const location = useLocation();
  const menuItems = menuData.menu;
  const submenuItems = menuData.submenu ?? [];
  const currentPath = normalizePathname(location.pathname);
  const showSubmenu = currentPath !== "/";


  return (
    <>
      <div className="bg-contrast grid grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] w-full items-center pl-3">
        <div className={styles.leftGroup}>
          <a href="/" className={styles.brandLink}>
            {userData.name}
          </a>
        </div>
        <div className={styles.logoContainer}>
          <img
            src={images.logo.src}
            alt={images.logo.alt}
            className={styles.logo}
          />
        </div>
        <nav
          aria-label="Primary navigation"
          className="col-start-3 row-start-1 p-4 justify-self-end bg-contrast"
        >
          <div className="container mx-auto flex justify-between items-center">
          {/* Desktop Menu */}
            <div className="hidden md:flex items-center gap-6">
              <ul className="flex space-x-6">
                {menuItems.map((item, index) => (
                  <li key={index}>
                    <a
                      href={item === "home" ? `/` : `/${item}`}
                      className="menu_desk text-main hover:text-secondary transition-colors duration-300"
                    >
                      {t(`menu.${item}`)}
                    </a>
                  </li>
                ))}
              </ul>
              <LanguageSelector data={data} />
            </div>

            {/* Mobile Menu Button */}
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="md:hidden text-main"
              aria-label={isOpen ? "Close menu" : "Open menu"}
            >
              {isOpen ? <FiX size={24} /> : <FiMenu size={24} />}
            </button>
          </div>
        </nav>

      </div>


      {/* Mobile Menu */}
      <div
        aria-hidden={!isOpen}
        className={`absolute left-0 top-full z-40 w-screen overflow-hidden md:hidden ${
          isOpen ? "" : "pointer-events-none"
        }`}
      >
        <div
          className={`bg-contrast shadow-xl px-4 pb-4 pt-2 transition-transform duration-300 ease-in-out ${
            isOpen ? "translate-x-0" : "-translate-x-full"
          }`}
        >
          <ul className="space-y-3 border-b border-main/10 pb-4">
            {menuItems.map((item, index) => (
              <li key={index}>
                <a
                  href={item === "home" ? `/` : `/${item}`}
                  className="menu_mobile block text-main py-2"
                  onClick={() => setIsOpen(false)}
                >
                  {t(`menu.${item}`)}
                </a>
              </li>
            ))}
          </ul>

          <ul className="space-y-3 py-4 border-b border-main/10">
            {submenuItems.map((item) => (
              <li key={item}>
                <a
                  href={`/${item}`}
                  className="menu_mobile block text-main"
                  onClick={() => setIsOpen(false)}
                >
                  {t(getSubmenuTranslationKey(item))}
                </a>
              </li>
            ))}
          </ul>

          <div className="pt-4">
            <LanguageSelector data={data} />
          </div>
        </div>
      </div>

      {showSubmenu ? (
        <nav
          aria-label="Section navigation"
          className="hidden sm:flex col-span-3 row-start-2 border-t border-main/10 bg-contrast/10 px-4 py-3 backdrop-blur-lg"
        >
          <ul className="mx-auto flex w-full max-w-[1400px] items-center justify-center gap-3 overflow-x-auto whitespace-nowrap">
            {submenuItems.map((item) => {
              const href = `/${item}`;
              const isActive = currentPath === href;

              return (
                <li key={item}>
                  <a
                    href={href}
                    className={`menu_desk inline-flex px-4 py-2 transition-colors duration-300 ${
                      isActive
                        ? "bg-secondary text-contrast"
                        : "text-main hover:bg-secondary/10 hover:text-secondary"
                    }`}
                  >
                    {t(getSubmenuTranslationKey(item))}
                  </a>
                </li>
              );
            })}
          </ul>
        </nav>
      ) : null}
    </>
  );
}


const styles = {
    leftGroup: "col-start-2 row-start-1 min-w-0 justify-self-center sm:col-start-1 sm:justify-self-auto",
    brandLink: "block text-main h1_mobile sm:h1_desk truncate ml-2 sm:ml-0 pr-0 sm:pr-2 py-1",
    logoContainer: "col-start-1 row-start-1 flex justify-center items-center sm:col-start-2",
    logo: "h-[60px]",
};
